  if (!isInstaller && !isRemoteRunner && !isUvRun && !isGoInstall) return;

  const packages = args.filter((a) => !a.startsWith('-') && !INSTALL_SUBCOMMANDS.has(a) && a !== 'run' && !/\.(txt|toml|lock|json|yaml|yml)$/.test(a) && a !== '.');
